INSERT INTO feature VALUES('glf-lc-syntax-model','descriptions','The λ-calculus syntax model with its six substitution laws','glf-model-in-source','implemented','uncommon','dependent provers','The pure λ-calculus''s single-substitution calculus as `theory LC` (Con, Sub, Tm; nine operations; the six substitution laws) and its syntax model `module LCSyntax : Model(LC)` over de Bruijn terms, renamings and substitutions: laws 1, 2, 5 and 6 by computation, 3 and 4 by induction on the term through four fusion lemmas; every law a `Path` field discharged by `become` of a top-level lemma; the module packed into the record of LC''s models and a β-step run through it; 94 declarations, kernel-sealed. Lifting is a constructor (a definition refuses by #761, the pathological twin); `theory LC` is hand-written as `Lambda`''s first-order translation (#2422); the theory''s own rules refuse `RulesUnoriented`, law 3 oriented by no path order, while `Model(LC)` derives from its presentation.','surface-corpus','corpus/model/desc/lc/ corpus/model/desc/lc/lift-as-definition.gandr','corpus/model/desc/lc/lift-as-definition.gandr','#640');
